<template>
  <main class="content"><div class="title"><div><div class="eyebrow">平台运营 / 核销员授权</div><h1>核销员授权</h1><p>为指定活动授权具备核销员角色的账号。</p></div></div><section class="panel assign"><h2>新增授权</h2><div class="form-row"><input v-model.number="form.activityId" type="number" placeholder="活动 ID" /><input v-model.number="form.userId" type="number" placeholder="核销员用户 ID" /><ChineseDateTimeInput v-model="form.validFrom" type="datetime-local" aria-label="授权开始时间" /><ChineseDateTimeInput v-model="form.validUntil" type="datetime-local" aria-label="授权结束时间" /><button @click="assign">授权</button></div><p>目标用户必须已经拥有 VERIFIER 角色。</p></section><section class="panel toolbar"><select v-model="enabled" @change="load"><option value="">全部授权</option><option value="true">生效中</option><option value="false">已停用</option></select><button @click="load">刷新</button></section><section class="panel table-wrap"><div v-if="loading" class="state">授权记录加载中...</div><div v-else-if="error" class="error">{{ error }} <button @click="load">重新加载</button></div><div v-else-if="!records.length" class="state">暂无授权记录</div><table v-else><thead><tr><th>活动</th><th>核销员</th><th>有效期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in records" :key="item.id"><td>{{ item.activityTitle }}<small>ID：{{ item.activityId }}</small></td><td><StaffIdentity :account="item" :subtitle="item.username + ' · ID：' + item.userId" /><small>{{ item.phone || '手机号未填写' }}</small></td><td>{{ formatDate(item.validFrom) }} 至 {{ formatDate(item.validUntil) }}</td><td><span class="status" :class="item.enabled ? 'enabled' : 'disabled'">{{ item.enabled ? '生效中' : '已停用' }}</span></td><td><button class="action" @click="toggle(item)">{{ item.enabled ? '停用' : '恢复' }}</button></td></tr></tbody></table></section></main>
</template>
<script setup>
import ChineseDateTimeInput from '../../components/ChineseDateTimeInput.vue'
import StaffIdentity from '../../components/StaffIdentity.vue'
import { onMounted, reactive, ref } from "vue"; import { platformVerifierApi } from "../../api/platformVerifier";
const records=ref([]),enabled=ref(""),loading=ref(false),error=ref("");const form=reactive({activityId:null,userId:null,validFrom:"",validUntil:""});const formatDate=v=>v?v.replace("T"," ").slice(0,16):"不限";
async function load(){loading.value=true;error.value="";try{records.value=await platformVerifierApi.list({enabled:enabled.value===""?undefined:enabled.value})||[];}catch(e){error.value=e?.message||"授权记录加载失败";}finally{loading.value=false;}}async function assign(){if(!form.activityId||!form.userId){error.value="请填写活动 ID 和核销员用户 ID";return;}try{await platformVerifierApi.assign({activityId:form.activityId,userId:form.userId,validFrom:form.validFrom||null,validUntil:form.validUntil||null});await load();}catch(e){error.value=e?.message||"授权失败";}}async function toggle(item){try{await platformVerifierApi.updateEnabled(item.id,!item.enabled);await load();}catch(e){error.value=e?.message||"状态更新失败";}}onMounted(load);
</script>
<style scoped>
.content{padding:34px;max-width:1500px}.title{margin-bottom:28px}.eyebrow{color:#6f7690;font-size:13px;margin-bottom:10px}h1{margin:0 0 8px;font-size:30px}.title p{margin:0;color:#6e7387}.panel{background:#fff;border:1px solid #e1e5ef;border-radius:10px;padding:22px;margin-bottom:20px}.assign h2{margin:0 0 16px;font-size:18px}.form-row,.toolbar{display:flex;gap:10px;align-items:center}.form-row input,.toolbar select{border:1px solid #dfe2ee;border-radius:7px;padding:9px 11px;background:#fafaff}.form-row button,.toolbar button,.action,.error button{border:1px solid #cfd8f4;border-radius:6px;padding:8px 13px;background:#f5f7ff;color:#0d50dc;cursor:pointer}.assign p{color:#737b90;font-size:13px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:900px}th,td{text-align:left;padding:15px;border-bottom:1px solid #ececf3}th{color:#61677a;font-size:13px}small{display:block;color:#858b9d;margin-top:5px}.status{display:inline-block;padding:5px 9px;border-radius:12px;font-size:12px}.enabled{background:#e0f8e9;color:#16834a}.disabled{background:#ffe7e7;color:#c53a43}.state{color:#737b90}.error{color:#c53a43}@media(max-width:700px){.content{padding:20px 14px}.form-row{flex-wrap:wrap}.form-row input{width:100%}}
</style>
